import com.bridger.momentum.*;
import java.util.*;
public final class ServerModeProbeRegression {
 static void platform(Map<String,Integer> cells,int gap,int rise,int dx,int dz){for(int side=-2;side<=2;side++)for(int depth=gap+1;depth<=gap+4;depth++)cells.put((100+dx*depth-dz*side)+","+(64+rise)+","+(100+dz*depth+dx*side),1);}
 public static void main(String[] args){for(int[] dir:new int[][]{{1,0},{-1,0},{0,1},{0,-1}})for(int gap:new int[]{16,28,51,83})for(int rise:new int[]{0,3,6}){Map<String,Integer> cells=new HashMap<>();platform(cells,gap,rise,dir[0],dir[1]);ServerModeProbe.Grid grid=(x,y,z)->cells.getOrDefault(x+","+y+","+z,0);ServerMode.Measurement m=ServerModeProbe.measure("mcplayhd.net",grid,100,64,100,dir[0],dir[1]);if(!m.available||m.gap!=gap||m.rise!=rise)throw new AssertionError("Incomplete run misclassified: "+gap+" / "+rise);if(ServerModeProbe.measure("other.net",grid,100,64,100,dir[0],dir[1]).available)throw new AssertionError("McPlay rule leaked");}Map<String,Integer> ambiguous=new HashMap<>();platform(ambiguous,16,0,0,1);platform(ambiguous,28,0,0,1);if(ServerModeProbe.measure("mcplayhd.net",(x,y,z)->ambiguous.getOrDefault(x+","+y+","+z,0),100,64,100,0,1).available)throw new AssertionError("Ambiguous islands guessed as Short");if(ServerModeProbe.measure("mcplayhd.net",(x,y,z)->0,100,64,100,0,1).available)throw new AssertionError("Unloaded island guessed");System.out.println("PASS: all four McPlay modes from finish-platform evidence before run completion, all axes/heights, server isolation and ambiguous/unloaded rejection");}
}
